const MODEL = 'sonnet';   // Claude Code alias: 'sonnet' or 'haiku' (lighter on your Pro limits)

const CANDIDATE_PROFILE = `PASTE_YOUR_FULL_CANDIDATE_PROFILE_HERE`;

// Must match what http://xelatex-api:8000/compile-resume expects
const RESUME_SCHEMA = {
  personal_information: { full_name: '', email: '', phone: '', github: '', linkedin: '' },
  PROFILE_SUMMARY: '3-4 sentence summary tailored to the offer',
  skills: { '<category_name>': ['skill', 'skill'] },
  experience: [{ title: '', company: '', location: '', dates: 'Mon YYYY – Mon YYYY', responsibilities: ['bullet'] }],
  education: [{ degree: '', institution: '', dates: '' }],
  certifications: ['']
};

const LETTER_SCHEMA = {
  COMPANY_NAME: '', JOB_TITLE: '', RECIPIENT_NAME: 'use "Madame, Monsieur" / "Hiring Manager" if unknown',
  PARAGRAPH_HOOK: '', PARAGRAPH_VALUE: '', PARAGRAPH_ALIGNMENT: '', PARAGRAPH_CTA: ''
};
// ======================

const jobOffer = $json.message.text;

const system = [
  'You are an expert career writer who tailors resumes and cover letters to job offers.',
  'Use ONLY facts from the candidate profile. Never invent experience, employers, dates, metrics or skills.',
  'You may reorder, select and rephrase content to emphasise what is most relevant to the offer.',
  'Write in the same language as the job offer.',
  'Output plain text only inside JSON values: no LaTeX, no Markdown, no HTML.',
  'Respond with ONE valid JSON object and nothing else: no code fences, no commentary.'
].join('\n');

const resumeRequest = {
  model: MODEL,
  max_tokens: 4096,
  system,
  messages: [{
    role: 'user',
    content:
      `<job_offer>\n${jobOffer}\n</job_offer>\n\n` +
      `<candidate_profile>\n${CANDIDATE_PROFILE}\n</candidate_profile>\n\n` +
      `Tailor the resume to this offer. Return JSON with EXACTLY these keys and structure ` +
      `(values shown are descriptions, replace them):\n` +
      JSON.stringify(RESUME_SCHEMA, null, 2)
  }]
};

const letterRequest = {
  model: MODEL,
  max_tokens: 2048,
  system,
  messages: [{
    role: 'user',
    content:
      `<job_offer>\n${jobOffer}\n</job_offer>\n\n` +
      `<candidate_profile>\n${CANDIDATE_PROFILE}\n</candidate_profile>\n\n` +
      `Write a concise, factual cover letter (each paragraph 2-4 sentences). Return JSON with EXACTLY these keys:\n` +
      JSON.stringify(LETTER_SCHEMA, null, 2)
  }]
};

return { json: { chatId: $json.message.chat.id, jobOffer, resumeRequest, letterRequest } };

